def select(study,group,target,condition=None,frame=a):
 x=frame[(frame.study==study)&(frame.grouping==group)&(frame.target==target)]
 if condition is not None:x=x[x.condition.map(json.loads).map(lambda c:c==condition)]
 return x.sort_values('day')
def matrix(x,percent=False):
 return [f"{r.positive}/{r.n} ({100*r['mean']:.1f}%)" if percent else f"{r['mean']:.3f} (n={r.n})" for _,r in x.iterrows()]
def mdtable(headers,rows):return ['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(str(v) for v in r)+' |' for r in rows]
